{
  "Name": "Client",
  "Key": "CRM",
  "ResourceKey": "CRM",
  "Script": "Client = {\n    init: async function (app, container) {\n        app = app || session.app;\n        container = container || $(\".component[name=Client]\");\n        var clientName = getQueryParameter(\"Name\");\n        var clientList = await api.get(\"DMS/\" + app.Config.CRM.ClientFolder + \"clientList.json\");\n        var clientEntry = clientList.filter(r => r.name == clientName)[0];\n        $(\"[name=name]\", container).val(clientEntry.name);\n        $(\"[name=contactInfo]\",container).val(clientEntry.contactInfo);\n        if (!clientEntry.contactInfo) {\n            clientEntry.contactInfo = { companyName: null, domain: null, technicalPhone: null, technicalEmail: null, salesPhone: null, salesEmail: null, projectManagerEmail: null, projectManagerEmail: null, history: null };\n        }\n        var model = kendo.observable(clientEntry.contactInfo);\n        kendo.bind($(\"[name=contactInfo]\", container), model);\n        loadComponent($(\"[name=apps]\", container), \"AppList\", async (appListComponent) => {\n            await appListComponent.init(app, $(\".component[name=AppList]\", $(\"[name=apps]\", container)), \"DMS/\" + app.Config.CRM.ClientFolder + \"/\" + clientEntry.name + \"/apps.json\");\n        });\n        loadComponent($(\"[name=history]\", container), \"HistoryList\", async (historyListComponent) => {\n            await historyListComponent.init(app, $(\".component[name=HistoryList]\", $(\"[name=history]\", container)), \"DMS/\" + app.Config.CRM.ClientFolder + \"/\" + clientEntry.name + \"/history.json\");\n        });\n        loadComponent($(\"[name=themes]\", container), \"ThemeList\", async (themeListComponent) => {\n            await themeListComponent.init(app, $(\".component[name=ThemeList]\", $(\"[name=themes]\", container)), \"DMS/\" + app.Config.CRM.ClientFolder + \"/\" + clientEntry.name + \"/themes.json\", clientEntry);\n        });\n        $(\"[name=contactToolbar]\").kendoToolBar({\n            items: [\n                {\n                    text: \"[resource_displayname[save]]\",\n                    type: \"button\",\n                    template: \"<a name=clientInfoSave style='position: absolute; top: 10px; right:20px; float:right;'><span class='k-icon k-i-save'></span> [resource_displayname[Save]]</a>\"\n                },\n            ]\n        });\n        $(\"a[name=clientInfoSave]\", container).on(\"click\", async function (e) { await Client.save(app, model, clientName) });\n    },\n\n    save: async function (app, clientContactInfo, clientName) {\n        var clientList = await api.get(\"DMS/\" + app.Config.CRM.ClientFolder + \"clientList.json\");\n        var clientEntry = clientList.filter(r => r.name == clientName)[0];\n        clientEntry.contactInfo = clientContactInfo;\n        clientEntry.lastUpdated = (new Date()).toISOString();\n        await api.put(\"DMS/\" + app.Config.CRM.ClientFolder + \"clientList.json\", clientList).then(() =>  notification.success(\"[resource_displayname[saved]]\"))\n        .catch((err) => error(err));\n    }\n}",
  "Content": "<div class=\"split50\">\r\n\t<h3 class = \"heading\">[resource_displayname[apps]]</h3>\r\n\t<div name=\"apps\" class = \"appsGrid\" ></div>\r\n\t<h3 class = \"heading\">[resource_displayname[themes]]</h3>\r\n\t<div name=\"themes\" class = \"themesGrid\">\r\n\t</div>\r\n</div>\r\n\r\n<div class=\"split50\">\r\n\t<h3 class=\"heading\">[resource_displayname[contactInfo]]</h3>\r\n\t<div name=\"contactToolbar\" class = \"contactToolbar\" ></div>\r\n\t<div name=\"contactInfo\" class = \"contactInfo\">\r\n\t\t<ul class=\"fieldList\">\r\n\t\t\t<li>\r\n\t\t\t\t<label>[resource_displayname[companyName]]</label>\r\n\t\t\t\t<div class=\"value\">\r\n\t\t\t\t\t<input name=\"name\" type=\"text\" data-bind=\"value:companyName\" />\r\n\t\t\t\t</div>\r\n\t\t\t</li>\r\n\t\t\t<li>\r\n\t\t\t\t<label>[resource_displayname[domain]]</label>\r\n\t\t\t\t<div class=\"value\">\r\n\t\t\t\t\t<input name=\"domain\" type=\"text\" data-bind=\"value:domain\" />\r\n\t\t\t\t</div>\r\n\t\t\t</li>\r\n\t\t\t<li>\r\n\t\t\t\t<label>[resource_displayname[technicalPhone]]</label>\r\n\t\t\t\t<div class=\"value\">\r\n\t\t\t\t\t<input name=\"technicalPhone\" type=\"text\" data-bind=\"value:technicalPhone\" />\r\n\t\t\t\t</div>\r\n\t\t\t</li>\r\n\t\t\t<li>\r\n\t\t\t\t<label>[resource_displayname[technicalEmail]]</label>\r\n\t\t\t\t<div class=\"value\">\r\n\t\t\t\t\t<input name=\"technicalEmail\" type=\"text\" data-bind=\"value:technicalEmail\" />\r\n\t\t\t\t</div>\r\n\t\t\t</li>\r\n\t\t\t<li>\r\n\t\t\t\t<label>[resource_displayname[salesPhone]]</label>\r\n\t\t\t\t<div class=\"value\">\r\n\t\t\t\t\t<input name=\"salesPhone\" type=\"text\" data-bind=\"value:salesPhone\" />\r\n\t\t\t\t</div>\r\n\t\t\t</li>\r\n\t\t\t<li>\r\n\t\t\t\t<label>[resource_displayname[salesEmail]]</label>\r\n\t\t\t\t<div class=\"value\">\r\n\t\t\t\t\t<input name=\"salesEmail\" type=\"text\" data-bind=\"value:salesEmail\" />\r\n\t\t\t\t</div>\r\n\t\t\t</li>\r\n\t\t\t<li>\r\n\t\t\t\t<label>[resource_displayname[projectManagerPhone]]</label>\r\n\t\t\t\t<div class=\"value\">\r\n\t\t\t\t\t<input name=\"projectManagerPhone\" type=\"text\" data-bind=\"value:projectManagerPhone\" />\r\n\t\t\t\t</div>\r\n\t\t\t</li>\r\n\t\t\t<li>\r\n\t\t\t\t<label>[resource_displayname[projectManagerEmail]]</label>\r\n\t\t\t\t<div class=\"value\">\r\n\t\t\t\t\t<input name=\"projectManagerEmail\" type=\"text\" data-bind=\"value:projectManagerEmail\" />\r\n\t\t\t\t</div>\r\n\t\t\t</li>\r\n\t\t</ul>\r\n\t</div>\r\n\t<h3 class = \"heading\" >[resource_displayname[history]]</h3>\r\n\t<div name=\"history\"  class = \"historyGrid\"></div>\r\n</div>\r\n\r\n<style scoped>\r\n\t.split50 { width: 49.5%; display: inline-block; vertical-align: top; margin: 0px; margin-right: 0px; padding: 0px; border: 0px; margin-right: -2px; }\r\n\t.component[name=Client] { max-height: 780px; overflow-y: auto; overflow-x: hidden; }\r\n\t.contactInfo { margin-left:10px; }\r\n\t.k-grid-content { min-height: 150px; }\r\n</style>",
  "LastUpdated": "2022-01-07T12:27:01.9748219+00:00"
}
"""
