            new PackageItem
            {
                Type = "Core/Component",
                Data = """
{
  "Name": "ClientFiles",
  "Key": "CRM",
  "ResourceKey": "CRM",
  "Script": "ClientFiles = {\r\n    init: async function (app, container, clientEntry) {\r\n        app = app || session.app;\r\n        container = container || $(\".component[name=ClientFiles]\");\r\n        await api.add(\"DMS/\" + app.Config.CRM.ClientFolder + clientEntry.name + \"/Content/Slideshow\");\r\n        await api.add(\"DMS/\" + app.Config.CRM.ClientFolder + clientEntry.name + \"/Content/Flags\");\r\n        await api.add(\"DMS/\" + app.Config.CRM.ClientFolder + clientEntry.name + \"/Content\");\r\n        var slideShowFolder = (await api.get(\"DocumentManagement/Folder?$filter=AppId eq \" + app.Id + \" and Path eq '\" + app.Config.CRM.ClientFolder + clientEntry.name + \"/Content/Slideshow' \")).value;\r\n        slideShowFolder = slideShowFolder[0];\r\n        var flagsFolder = (await api.get(\"DocumentManagement/Folder?$filter=AppId eq \" + app.Id + \" and Path eq '\" + app.Config.CRM.ClientFolder + clientEntry.name + \"/Content/Flags' \")).value;\r\n        flagsFolder = flagsFolder[0];\r\n        var contentFolder = (await api.get(\"DocumentManagement/Folder?$filter=AppId eq \" + app.Id + \" and Path eq '\" + app.Config.CRM.ClientFolder + clientEntry.name + \"/Content' \")).value;\r\n        contentFolder = contentFolder[0];\r\n        loadComponent($(\"[name=folderManagementSlideshow]\", container), \"FolderManagement\", (comp) => {\r\n            comp.init(app, $(\"[name=folderManagementSlideshow]\", container), slideShowFolder, false, true, true);\r\n        });\r\n        loadComponent($(\"[name=folderManagementFlags]\", container), \"FolderManagement\", (comp) => {\r\n            comp.init(app, $(\"[name=folderManagementFlags]\", container), flagsFolder, false, true, true);\r\n        });\r\n        loadComponent($(\"[name=folderManagementContent]\", container), \"FolderManagement\", (comp) => {\r\n            comp.init(app, $(\"[name=folderManagementContent]\", container), contentFolder, false, true, true);\r\n        });\r\n        $(\".partsList > ul > li\", container).on(\"click\", function (e) {\r\n            $(\".partsList > ul > li\", container).removeClass(\"selected\");\r\n            $(\".sectionContainer\", container).css(\"display\", \"none\");\r\n            $(\".sectionContainer[name=\" + $(e.target).attr(\"data-container\") + \"]\").css(\"display\", \"inline-block\");\r\n            $(e.target).addClass(\"selected\");\r\n        });\r\n        $(\".sectionContainer\", container).hide();\r\n        $(\".sectionContainer[name=\" + $(\".partsList > ul > li.selected\", container).attr(\"data-container\") + \"]\").show();\r\n    }\r\n}",
  "Content": "<div class=\"partsList\">\r\n\t<ul>\r\n\t\t<li class=\"selected\" data-container=\"slideshowContainer\">[resource_displayname[slideshow]]</li>\r\n\t\t<li data-container=\"flagsContainer\">[resource_displayname[flags]]</li>\r\n\t\t<li data-container=\"contentContainer\">[resource_displayname[content]]</li>\r\n\t</ul>\r\n</div>\r\n<div name=\"slideshowContainer\" class=\"sectionContainer\">\r\n\t<div name=\"folderManagementSlideshow\"></div>\r\n</div>\r\n<div name=\"flagsContainer\" class=\"sectionContainer\">\r\n\t<div name=\"folderManagementFlags\"></div>\r\n</div>\r\n<div name=\"contentContainer\" class=\"sectionContainer\">\r\n\t<div name=\"folderManagementContent\"></div>\r\n</div>\r\n<hr>\r\n<div class=\"value\">\r\n\t<button style=\"float:right\" name=\"confirm\">[resource_displayname[confirm]]</button>\r\n</div>\r\n<style>\r\n\t.component[name=ClientFiles] { width: 1300px; overflow:hidden;}\r\n\t[name=ClientFiles] .partsList { height: 321px;  width: 320px; display: inline-block; vertical-align: top; border-right: solid 1px #ccc; }\r\n\t[name=ClientFiles] .partsList > ul { padding: 10px; }\r\n\t[name=ClientFiles] .partsList > ul > li { margin: 2px; padding: 10px; cursor: pointer; background: #ccc; width: 70%; }\r\n\t[name=ClientFiles] .partsList > ul > li.selected { font-weight: bold; background: #ddd; width: 96%; }\r\n\t[name=ClientFiles] >.sectionContainer { width: 73.5%; display: inline-block; vertical-align: top; padding:10px; }\r\n\t[name=ClientFiles] > .value > button { float: right; margin: 8px 10px; }\r\n\t</style>",
  "LastUpdated": "2023-05-12T11:16:45.4312442+01:00"
}
"""
