            {
                Type = "Core/Component",
                Data = """
{
  "Name": "HistoryList",
  "Key": "CRM",
  "ResourceKey": "CRM",
  "Script": "HistoryList = {\r\n    init: async function (app, container, historyDMSPath) {\r\n        app = app || session.app;\r\n        container = container || $(\".component[name=HistoryList]\");\r\n        var history = await api.get(historyDMSPath);\r\n        var historyGrid = new GridWidget($(\"[name=historyGrid]\",container), {data: history});\r\n        historyGrid.toolbar =\"<button name='add'><span class='k-icon k-i-add'></span>[resource_displayname[add]]</button><button name='save'><span class='k-icon k-i-save'></span>[resource_displayname[save]]</button>\";\r\n        historyGrid.groupable = false;\r\n        historyGrid.pageable = false;\r\n        historyGrid.columns = [\r\n            { field: \"created\", title: \"[resource_displayname[created]]\", format: \"{0:\" + type.dateFormat + \"}\", type: \"date\", width: 160, title: \"[resource_displayname[created]]\" },\r\n            { field: \"content\", title: \"[resource_displayname[content]]\", title: \"[resource_displayname[content]]\" }\r\n        ];\r\n        historyGrid.commands.push({ name: \"edit\", icon: \"k-i-edit\", text: \"[resource_displayname[edit]]\" });\r\n        historyGrid.commands.push({ name: \"remove\", icon: \"k-i-delete\", text: \"[resource_displayname[delete]]\" });\r\n        historyGrid.dataBound = function () {\r\n            $(\"[name=remove]\", historyGrid.gridElement).on(\"click\", async function (e) { \r\n                var item = historyGrid.kendoObject.dataItem($(e.currentTarget).closest(\"tr\"));\r\n                await HistoryList.removeHistory(e, historyGrid, item); \r\n            });\r\n            $(\"[name=edit]\", historyGrid.gridElement).on(\"click\", async function (e) {\r\n                var item = historyGrid.kendoObject.dataItem($(e.currentTarget).closest(\"tr\"));\r\n                await HistoryList.editHistory(item, historyGrid);\r\n            });\r\n        };\r\n        await historyGrid.init();\r\n        $(\"[name=add]\", historyGrid.gridElement).on(\"click\", async function (e) { await HistoryList.addHistory(e, historyGrid); });\r\n        $(\"[name=save]\", historyGrid.gridElement).on(\"click\", async function (e) { await HistoryList.save( historyGrid, historyDMSPath); });\r\n    },\r\n\r\n    save: async function (historyGrid, historyDMSPath) {\r\n        await api.put(historyDMSPath, historyGrid.kendoObject.dataSource.data()).then(() => {\r\n            notification.success(\"[resource_displayname[saved]]\");\r\n            historyGrid.kendoObject.refresh();\r\n        }).catch((err) => { error(err); });\r\n    },\r\n\r\n    addHistory: function (e, historyGrid) {\r\n        var addHistoryDialog = new Dialog({ title: \"[resource_displayname[AddHistory]]\", width: 700, height: 350 });\r\n        addHistoryDialog.template = $(\"[name=addHistoryDialog]\").html();\r\n        addHistoryDialog.events.confirm = async function () {\r\n            var model = { created: (new Date()).toISOString(), content: $(\"[name=history]\", addHistoryDialog.element).data(\"kendoEditor\").value() }\r\n            historyGrid.kendoObject.dataSource.insert(0, model);\r\n            historyGrid.kendoObject.refresh();\r\n            addHistoryDialog.events.close();\r\n        };\r\n        addHistoryDialog.init(() => {\r\n            $(\"[name=history]\", addHistoryDialog.element).kendoEditor();\r\n        });\r\n    },\r\n\r\n    editHistory: async function (historyEntry, historyGrid) {\r\n        var editHistoryDialog = new Dialog({ title: \"[resource_displayname[edithistory]]\", width: 700, height: 350 });\r\n        editHistoryDialog.template = $(\"[name=editHistoryDialog]\").html();\r\n        editHistoryDialog.events.confirm = async function () {\r\n            historyEntry.content = $(\"[name=editHistory]\", editHistoryDialog.element).data(\"kendoEditor\").value();\r\n            historyGrid.kendoObject.refresh();\r\n            editHistoryDialog.events.close();\r\n        };\r\n        editHistoryDialog.init(() => {\r\n            $(\"[name=editHistory]\", editHistoryDialog.element).kendoEditor().data(\"kendoEditor\").value(historyEntry.content);\r\n        });\r\n    },\r\n\r\n    removeHistory: async function (e, historyGrid, historyEntry) {\r\n        historyGrid.kendoObject.dataSource.remove(historyEntry);\r\n    }\r\n}",
  "Content": "<div name=\"historyGrid\"></div>\r\n<script type=\"text/template\" name=\"addHistoryDialog\">\r\n\t<div>\r\n<div class=\"value\" style=\"width:650px; margin: 20px\"><textarea name=\"history\" type=\"text\" data-bind=\"value: history\" ></textarea></div>\r\n</div>\r\n<hr>\r\n<div class=\"value\">\r\n\t<button style=\"float:right;\" name=\"confirm\">[resource_displayname[AddHistory]]</button>\r\n</div>\r\n</script>\r\n\r\n<script type=\"text/template\" name=\"editHistoryDialog\">\r\n\t<div style=\"overflow:hidden\">\r\n\t\t<div class=\"value\" style=\"width:650px; margin: 20px\">\r\n\t\t\t<textarea name=\"editHistory\" type=\"text\" data-bind=\"value: history\" ></textarea>\r\n\t\t\t</div>\r\n\t</div>\r\n\t<hr>\r\n\t<div class=\"value\">\r\n\t\t<button style=\"float:right;\" name=\"confirm\">[resource_displayname[editHistory]]</button>\r\n\t</div>\r\n</script>",
  "LastUpdated": "2021-11-19T21:27:06.7810571+00:00"
}
