            new PackageItem
            {
                Type = "Core/Component",
                Data = """
{
  "Name": "TenantAppManagement",
  "Key": "CRM",
  "ResourceKey": "CRM",
  "Script": "TenantAppManagement = {\r\n    init: async function (app, container, tenant) {\r\n        app = app || session.app;\r\n        container = container || $(\".component[name=TenantAppManagement]\");\r\n        if (!tenant)\r\n            return;\r\n\r\n        api.addToMetaCache([\r\n            {\r\n                \"Name\": \"Core\",\r\n                \"Types\": [\r\n                    [meta[ContentManagement/App]]\r\n                ]\r\n            }\r\n        ]);\r\n        TenantAppManagement.buildAppGrid(container, app, tenant);\r\n    },\r\n\r\n    add: async function(e, tenant, app, appGrid) {\r\n        e.preventDefault();\r\n\r\n        var domainSuffix = app.Config.CRM.EnvironmentUrlSuffix || location.hostname.split('.').slice(-3).join('.');\r\n\r\n        var d = new EditorDialog({\r\n            title: \"[resource_displayname[addapp]]\",\r\n            confirm: \"<span class='k-icon k-i-plus'></span>[resource_displayname[add]]\",\r\n            data: {\r\n                Name: tenant.Name,\r\n                CompanyName: '',\r\n                Domain: `.${domainSuffix}`,\r\n                SourceAppId: 0,\r\n                Password: \"\"\r\n            },\r\n            fields: [\r\n                { field: \"Name\", title: \"[resource_displayname[name]]\" },\r\n                { field: \"CompanyName\", title: \"[resource_displayname[companyname]]\" },\r\n                { field: \"SourceAppId\", title: \"[resource_displayname[sourceappid]]\" },\r\n                { field: \"Password\", title: \"[resource_displayname[password]]\", fieldType: \"password\" }\r\n            ]\r\n        });\r\n        d.events.confirm = () => TenantAppManagement.buildPortal(d, app, tenant, appGrid);\r\n        d.init();\r\n        let ds = await model.getDatasource({ endpoint: \"ContentManagement/App\" });\r\n        $(\"input[name=SourceAppId]\", d.element).kendoDropDownList({\r\n            optionLabel: \"[resource_displayname[noSourceApp]]\",\r\n            dataTextField: \"Name\",\r\n            dataValueField: \"Id\",\r\n            dataSource: ds\r\n        });\r\n    },\r\n\r\n    buildAppGrid: async function (container, app, tenant) {\r\n        var appData = await model.getDatasource({ endpoint: \"ContentManagement/App\", odataAppend: \"?$filter=TenantId eq '\" + tenant.Id + \"'\" });\r\n        var appGrid = new GridWidget(container, appData);\r\n        appGrid.toolbar = \"<button class='btn btn-sm btn-primary' name='add'><span class='k-icon k-i-plus'></span>[resource_displayname[add]]</button>\";\r\n        appGrid.groupable = false;\r\n        appGrid.pageable = false;\r\n        appGrid.filterable = true;\r\n        appGrid.editable = false;\r\n        appGrid.columns = [\r\n            { field: \"Name\", title: \"[resource_shortdisplayname[Name]]\" },\r\n            { field: \"Domain\", title: \"[resource_shortdisplayname[Domain]]\" },\r\n        ];\r\n        await appGrid.init();\r\n        $(\"[name=add]\", appGrid.gridElement).on(\"click\", (e) =>  TenantAppManagement.add(e, tenant, app, appGrid));\r\n    },\r\n\r\n    buildPortal: async function(d, app, tenant, appGrid){\r\n        notification.info(\"[resource_displayname[creatingapp]]\");\r\n\r\n        if(d.data.SourceAppId == 0) {\r\n            await TenantAppManagement.buildEmptyPortal(d, app, tenant, appGrid);\r\n            return;\r\n        }\r\n\r\n        var newApi = await TenantAppManagement.createNewApp(d, tenant);\r\n        await TenantAppManagement.createDMSFolders(newApi);\r\n        await TenantAppManagement.importPackages(d, newApi);\r\n        await TenantAppManagement.setupConfig(d, tenant, newApi);\r\n        await TenantAppManagement.unpackContentFolder(newApi, tenant, d.data.SourceAppId);\r\n        await TenantAppManagement.linkAdmins(app, newApi);\r\n        var ssoUser = await TenantAppManagement.createBuyerAdminAccount(newApi, d.data.Name);\r\n        await TenantAppManagement.createRootBucket(newApi, tenant);\r\n        await TenantAppManagement.copyWorkflowsTriggersAndSchedules(newApi, ssoUser.id, d.data.SourceAppId);\r\n        notification.success(\"[resource_displayname[created]]\");\r\n        appGrid.refresh();\r\n        d.events.close();\r\n    },\r\n\r\n    buildEmptyPortal: async function(d, app, tenant, appGrid) {\r\n        var newApi = await TenantAppManagement.createNewEmptyApp(d, tenant);\r\n        notification.success(\"[resource_displayname[created]]\");\r\n        appGrid.refresh();\r\n        d.events.close();\r\n    },\r\n\r\n    importPackages: async function (d, newApi) {\r\n        var packages = (await api.get(\"ContentManagement/App(\" + d.data.SourceAppId + \")/Export()?$expand=Items\")).value;\r\n        for (let i = 0; i < packages.length; i++) {\r\n            await newApi.post(\"Packaging/Package/ImportThis?appId=\" + newApi.app.Id, [packages[i]]);\r\n        };\r\n    },\r\n\r\n    createNewApp: async function (d, tenant) {\r\n        var sourceApp = await api.get(\"ContentManagement/App(\" + d.data.SourceAppId + \")?$expand=Cultures\");\r\n\r\n        var config = JSON.parse(sourceApp.ConfigJson);\r\n\r\n        var newApp = await api.post(\"ContentManagement/App\", {\r\n            TenantId: tenant.Id,\r\n            Domain: d.data.Name.toLowerCase().replaceAll(' ', '-') + d.data.Domain,\r\n            Name: d.data.Name,\r\n            ConfigJson: JSON.stringify(config, null, 4),\r\n            DefaultTheme: sourceApp.DefaultTheme,\r\n            DefaultCultureId: sourceApp.DefaultCultureId,\r\n            Cultures: sourceApp.Cultures.map(c => ({\r\n                CultureId: c.CultureId\r\n            }))\r\n        });\r\n        var newApi = new Api({ apiRoot: \"https://\" + newApp.Domain + \"/Api/\" });\r\n        newApi.app = newApp;\r\n        await newApi.login(session.user, d.data.Password, true);\r\n        return newApi;\r\n    },\r\n\r\n    createNewEmptyApp: async function(d, tenant) {\r\n        var newApp = await api.post(\"ContentManagement/App\", {\r\n            TenantId: tenant.Id,\r\n            Domain: d.data.Name.toLowerCase().replaceAll(' ', '-') + d.data.Domain,\r\n            Name: d.data.Name,\r\n            ConfigJson: JSON.stringify({\r\n                \"Themes\": {\r\n                    \"Default\": {}\r\n                }\r\n            }, null, 4),\r\n            DefaultTheme: 'Default',\r\n            DefaultCultureId: '',\r\n            Cultures: []\r\n        });\r\n        var newApi = new Api({ apiRoot: \"https://\" + newApp.Domain + \"/Api/\" });\r\n        newApi.app = newApp;\r\n        await newApi.login(session.user, d.data.Password, true);\r\n        return newApi;\r\n    },\r\n\r\n    createDMSFolders: async function (newApi) {\r\n        await newApi.post(\"DMS/Data/Transactions/Received\");\r\n        await newApi.post(\"DMS/Data/Transactions/Processed\");\r\n        await newApi.post(\"DMS/Data/Transactions/Transformed\");\r\n        await newApi.post(\"DMS/Data/Masterdata/Received\");\r\n        await newApi.post(\"DMS/Data/Masterdata/Processed\");\r\n        await newApi.post(\"DMS/Data/Masterdata/Transformed\");\r\n        await newApi.post(\"DMS/Content/Flags\");\r\n        await newApi.post(\"DMS/Content/Slideshow\");\r\n                    },\r\n\r\n    unpackContentFolder: async function (newApi, tenant, sourceAppId) {\r\n        var app = await api.get(\"ContentManagement/App(\" + sourceAppId + \")\");\r\n\r\n        try {\r\n            var blob = await new Promise(function (resolve, reject) {\r\n                var sourceReq = new XMLHttpRequest();\r\n                sourceReq.open(\"GET\", window.location.protocol + \"//\" + app.Domain + \"/Api/DMS/Content\" + \"?t=\" + session.token, true);\r\n                sourceReq.setRequestHeader(\"Authorization\", \"bearer \" + session.token);\r\n                sourceReq.responseType = \"blob\";\r\n                sourceReq.onload = function (oEvent) {\r\n                    if (this.readyState === 4 && this.status >= 200 & this.status <= 300) {\r\n                        resolve(this.response);\r\n                    } else {\r\n                        reject(this.status);\r\n                    }\r\n                };\r\n                sourceReq.send();\r\n            });\r\n        } catch(error) {\r\n            console.log(error);\r\n            notification.error('[resource_displayname[failedToPackDmsContent]]');\r\n        }\r\n\r\n        try {\r\n            await new Promise(function (resolve, reject) {\r\n                var destReq = new XMLHttpRequest();\r\n                destReq.open(\"PUT\", newApi.apiRoot + \"DMS/?unpack\" , true);\r\n                destReq.setRequestHeader(\"Authorization\", \"bearer \" + newApi.token);\r\n                destReq.setRequestHeader(\"Content-Type\", \"application/zip\");\r\n                destReq.onload = function (oEvent) {\r\n                    if (this.readyState === 4 && this.status >= 200 && this.status <= 300) {\r\n                        resolve(this.response);\r\n                    } else {\r\n                        reject(this.status);\r\n                    }\r\n                };\r\n                destReq.send(blob);\r\n            });\r\n        } catch(error) {\r\n            console.log(error);\r\n            notification.error('[resource_displayname[failedToUnpackDmsContent]]');\r\n        }\r\n\r\n        try {\r\n            var blob = await new Promise(function (resolve, reject) {\r\n                var sourceReq = new XMLHttpRequest();\r\n                sourceReq.open(\"GET\", \"/Api/DMS/CRM/\" + tenant.Id + \"/Theme/Content\" + \"?t=\" + session.token, true);\r\n                sourceReq.setRequestHeader(\"Authorization\", \"bearer \" + session.token);\r\n                sourceReq.responseType = \"blob\";\r\n                sourceReq.onload = function (oEvent) {\r\n                    if (this.readyState === 4 && this.status >= 200 & this.status <= 300) {\r\n                        resolve(this.response);\r\n                    } else {\r\n                        reject(this.status);\r\n                    }\r\n                };\r\n                sourceReq.send();\r\n            });\r\n        } catch(error) {\r\n            console.log(error);\r\n            notification.error('[resource_displayname[failedToPackThemeContent]]');\r\n        }\r\n\r\n        try {\r\n            await new Promise(function (resolve, reject) {\r\n                var destReq = new XMLHttpRequest();\r\n                destReq.open(\"PUT\", newApi.apiRoot + \"DMS/?unpack\" , true);\r\n                destReq.setRequestHeader(\"Authorization\", \"bearer \" + newApi.token);\r\n                destReq.setRequestHeader(\"Content-Type\", \"application/zip\");\r\n                destReq.onload = function (oEvent) {\r\n                    if (this.readyState === 4 && this.status >= 200 && this.status <= 300) {\r\n                        resolve(this.response);\r\n                    } else {\r\n                        reject(this.status);\r\n                    }\r\n                };\r\n                destReq.send(blob);\r\n            });\r\n        } catch(error) {\r\n            console.log(error);\r\n            notification.error('[resource_displayname[failedToUnpackThemeContent]]');\r\n        }\r\n    },\r\n\r\n    linkAdmins: async function(app, newApi){\r\n        var admins = await api.get(\"AppSecurity/UserRole?$filter=Role/AppId eq \" + app.Id + \"and Role/Name eq 'Administrators' and UserId ne '\" + session.user + \"'\");\r\n        var adminRole = (await api.get(\"AppSecurity/Role?$filter=AppId eq \" + newApi.app.Id + \" and Name eq 'Administrators'\")).value[0];\r\n        var userRole = (await api.get(\"AppSecurity/Role?$filter=AppId eq \" + newApi.app.Id + \" and Name eq 'Users'\")).value[0];\r\n        var adminRoleId = adminRole.Id;\r\n        var userRoleId = userRole.Id;\r\n        for (let i = 0; i < admins.value.length; i++){\r\n            var adminEntry = admins.value[i];\r\n            await newApi.post(\"AppSecurity/UserRole\", {\r\n                UserId: adminEntry.UserId,\r\n                RoleId: adminRoleId\r\n            });\r\n            await newApi.post(\"AppSecurity/UserRole\", {\r\n                UserId: adminEntry.UserId,\r\n                RoleId: userRoleId\r\n            });\r\n        }\r\n    },\r\n\r\n    createBuyerAdminAccount: async function (newApi, appName) {\r\n        var ssoUser = await newApi.register({\r\n            DisplayName: appName + \".admin\",\r\n            Email: appName.replaceAll(' ', '') + \".admin@' + (newApi.app.Domain || location.hostname)\",\r\n            Password: Guid().replaceAll(\"-\", \"\") + \"A!\",\r\n            Culture: newApi.app.DefaultCultureId,\r\n            PhoneNumber: \"\",\r\n            AppId: newApi.app.Id\r\n        });\r\n        var userId = ssoUser.id;\r\n        var appInfo = await newApi.get(\"ContentManagement/App(\" + newApi.app.Id + \")?$select=ConfigJson\");\r\n        /* b2b onboarding */\r\n        var config = JSON.parse(appInfo.ConfigJson);\r\n        var rootBucketId = config.B2B.RootBucket;\r\n        var buyerAdminRoleId = (await newApi.get(\"B2B/BucketRole?$filter=Bucket/ParentId eq \" + rootBucketId + \" and (contains(Role/Name, 'Buyer') or contains(Role/Name, 'Debtor'))\")).value[0].RoleId;\r\n        var userIsBuyerAdmin = (await newApi.get(`B2B/B2BUserRole?$filter=UserId eq '${userId}' and RoleId eq ${buyerAdminRoleId}`)).value.length > 0;\r\n        if(!userIsBuyerAdmin)\r\n            await newApi.post(\"B2B/B2BUserRole\", {\r\n                UserId: userId,\r\n                RoleId: buyerAdminRoleId\r\n            }).catch((err) => error(err));\r\n        \r\n        /* core onboarding */\r\n        var coreBuyerRoleId = (await newApi.get(\"AppSecurity/Role?$filter=contains(Name, 'Buyer') and AppId eq \" + newApi.app.Id)).value[0].Id;\r\n        await newApi.post(\"AppSecurity/UserRole\", {\r\n            UserId: userId,\r\n            RoleId: coreBuyerRoleId\r\n        }).catch((err) => error(err));\r\n\r\n        var coreAdminRoleId = (await newApi.get(\"AppSecurity/Role?$filter=contains(Name, 'Admin') and AppId eq \" + newApi.app.Id)).value[0].Id;\r\n        await newApi.post(\"AppSecurity/UserRole\", {\r\n            UserId: userId,\r\n            RoleId: coreAdminRoleId\r\n        }).catch((err) => error(err));\r\n\r\n        notification.success(\"[resource_displayname[adminusercreated]]\");\r\n\r\n        return ssoUser;\r\n    },\r\n\r\n    copyWorkflowsTriggersAndSchedules: async function(newApi, userId, sourceAppId) {\r\n        var transactionsReceivedEvents = (await api.get(`Workflow/WorkflowEvent?$expand=Flow&$filter=Type eq 'DocumentManagement/File' and EventContext eq 'App(${sourceAppId})/DMS(File_Created)/data/transactions/received'`)).value;\r\n        var masterdataReceivedEvents = (await api.get(`Workflow/WorkflowEvent?$expand=Flow&$filter=Type eq 'DocumentManagement/File' and EventContext eq 'App(${sourceAppId})/DMS(File_Created)/data/masterdata/received'`)).value;\r\n        var scheduledTasks = (await api.get(`Workflow/ScheduledTask?$filter=AppId eq ${sourceAppId}&$expand=Flow`)).value;\r\n        var appWorkflows = (await api.get(`Workflow/FlowDefinition?$filter=AppId eq ${newApi.app.Id}`)).value;\r\n\r\n        for(var event of transactionsReceivedEvents) {\r\n            var matchedFlow = appWorkflows.filter(wf => wf.Name == event.Flow.Name)[0];\r\n\r\n            if(matchedFlow) {\r\n                await newApi.post('Workflow/WorkflowEvent', {\r\n                    Type: \"DocumentManagement/File\",\r\n                    EventContext: \"App(\" + newApi.app.Id + \")/DMS(File_Created)/data/transactions/received\",\r\n                    FlowId: matchedFlow.Id,\r\n                    ExecuteAs: userId\r\n                });\r\n            }\r\n        }\r\n\r\n        for(var event of masterdataReceivedEvents) {\r\n            var matchedFlow = appWorkflows.filter(wf => wf.Name == event.Flow.Name)[0];\r\n\r\n            if(matchedFlow) {\r\n                await newApi.post('Workflow/WorkflowEvent', {\r\n                    Type: \"DocumentManagement/File\",\r\n                    EventContext: \"App(\" + newApi.app.Id + \")/DMS(File_Created)/data/masterdata/received\",\r\n                    FlowId: matchedFlow.Id,\r\n                    ExecuteAs: userId\r\n                });\r\n            }\r\n        }\r\n\r\n        for(var task of scheduledTasks) {\r\n            var matchedFlow = appWorkflows.filter(wf => wf.Name == task.Flow.Name)[0];\r\n\r\n            if(matchedFlow) {\r\n                await newApi.post('Workflow/ScheduledTask', {\r\n                    AppId: newApi.app.Id,\r\n                    FlowId: matchedFlow.Id,\r\n                    Name: task.Name,\r\n                    Description: task.Description,\r\n                    ExecutionArgs: task.ExecutionArgs,\r\n                    ScheduleInTicks: task.ScheduleInTicks,\r\n                    ExecuteAs: userId,\r\n                    NextExecution: task.NextExecution\r\n                });\r\n            }\r\n        }\r\n    },\r\n\r\n    createRootBucket: async function (newApi, tenant) {\r\n        var existing = (await api.get(`B2B/Bucket?$filter=Path eq '${tenant.Name}'`)).value[0];\r\n        if(existing == null) {\r\n            var rootBucket = await newApi.post('B2B/Bucket/AddClientRoot?name=' + tenant.Name + '&description=Root bucket for ' + newApi.app.Domain + '&sourceSystems=' + tenant.Name);\r\n            \r\n            await TenantAppManagement.linkAdminsToRootBucket(newApi, rootBucket.Id);\r\n        } else {\r\n            /*var types = [\r\n                { key: 'DebtorGroup', name: 'Buyers' },\r\n                { key: 'CreditorGroup', name: 'Suppliers' },\r\n                { key: 'FunderGroup', name: 'Funders' }\r\n            ];\r\n\r\n            for(var i = 0; i < types.length; i++) {\r\n                var t = types[i];\r\n\r\n                await api.post('B2B/Bucket', {\r\n                    Path: `${existing.Path}/${companyName}-${t.key}-${t.name}`,\r\n                    ParentId: existing.Id,\r\n                    Name: `${companyName} ${t.name} Group`,\r\n                    Description: `${t.name} Group for ${companyName}`,\r\n                    Key: t.key,\r\n                });\r\n            }*/\r\n        }\r\n\r\n        var config = JSON.parse(newApi.app.ConfigJson);\r\n        config.B2B.RootBucket = existing != null\r\n            ? existing.Id\r\n            : rootBucket.Id;\r\n        newApi.app.ConfigJson = JSON.stringify(config, null, 4);\r\n        await newApi.update(\"ContentManagement/App(\" + newApi.app.Id + \")\", newApi.app);\r\n    },\r\n\r\n    linkAdminsToRootBucket: async function (newApi, rootBucketId) {\r\n        var bucketAdminRole = (await newApi.get(\"B2B/BucketRole?$filter=BucketId eq \" + rootBucketId + \" and contains(Role/Name, 'Bucket Admins')\")).value[0];\r\n        var admins = await api.get(\"AppSecurity/UserRole?$filter=Role/AppId eq \" + newApi.app.Id + \"and Role/Name eq 'Administrators' and UserId ne '\" + session.user + \"'\");\r\n        var bucketAdminRoleId = bucketAdminRole.RoleId;\r\n        for (let i = 0; i < admins.value.length; i++) {\r\n            var adminEntry = admins.value[i];\r\n            await newApi.post(\"B2B/B2BUserRole\", { UserId: adminEntry.UserId, RoleId: bucketAdminRoleId });\r\n        }\r\n    },\r\n\r\n    createSourceSystem: async function (newApi, rootBucketId, tenant){\r\n        var systemExists = await newApi.get(\"B2B/System?$filter=Id eq '\" + tenant.Name + \"'\");\r\n        if (systemExists.value.length == 0) {\r\n            await newApi.post(\"B2B/System\", {\r\n                Name: tenant.Name,\r\n                Description: tenant.Name,\r\n                Id: tenant.Name\r\n            });\r\n        }\r\n        await newApi.post(\"B2B/BucketSystem\", {BucketId: rootBucketId, SystemId: tenant.Name});\r\n    },\r\n\r\n    setupConfig: async function (d, tenant, newApi) {\r\n        var sourceApp = await api.get(\"ContentManagement/App(\" + d.data.SourceAppId + \")\");\r\n        var config = JSON.parse(sourceApp.ConfigJson);\r\n        var calendar = (await api.get(\"Workflow/Calendar?$filter=AppId eq \" + newApi.app.Id)).value[0];\r\n        if(calendar != null)\r\n            config.Calendars.primary = calendar.Id;\r\n        else {\r\n            var calendar = {\r\n                Id: 0,\r\n                AppId: newApi.app.Id,\r\n                Name: 'primary'\r\n            };\r\n\r\n\t\t\tawait newApi.add(\"Workflow/Calendar\", calendar).then(async (calendarCreated) => {\r\n                config.Calendars[calendarCreated.Name] = calendarCreated.Id;\r\n                newApi.app.ConfigJson = JSON.stringify(config);\r\n                await newApi.put(\"ContentManagement/App(\" + newApi.app.Id + \")\", newApi.app)\r\n                    .catch((err) => error(err));\r\n            }).catch((err) => error(err));\r\n        }\r\n        \r\n        config.B2B.SourceSystem = tenant.Name;\r\n        config.B2B.TransactionSource = tenant.Name;\r\n        var domainName = newApi.app.Domain.split(\".\")[0];\r\n        config.Deployment = {\\r\\n            \"Targets\": [],\\r\\n            \"DMS\": [\\r\\n                \"Content\",\\r\\n                \"Content/Flags\",\\r\\n                \"Content/Slideshow\"\\r\\n            ],\\r\\n            \"TenantId\": tenant.Id\\r\\n        },\\r\\n        newApi.app.ConfigJson = JSON.stringify(config, null, 4);\r\n        await api.put(\"ContentManagement/App(\" + newApi.app.Id + \")\", newApi.app);\r\n    },\r\n}",
  "Content": "",
  "LastUpdated": "2025-12-04T13:19:10.1868037+00:00"
}
