{
  "Name": "TenantManagement",
  "Key": "CRM",
  "ResourceKey": "CRM",
  "Script": "TenantManagement = {\r\n    init: async function (app, container) {\r\n        app = app || session.app;\r\n        container = container || $(\".component[name=TenantManagement]\");\r\n        \r\n        api.addToMetaCache([\r\n            {\r\n                \"Name\": \"Security\",\r\n                \"Types\": [\r\n                    [meta[Security/Tenant]]\r\n                ]\r\n            },\r\n            {\r\n                \"Name\": \"B2B\",\r\n                \"Types\": [\r\n                    [meta[B2B/Country]]\r\n                ]\r\n            }\r\n        ]);\r\n\r\n        var tenantData = await model.getDatasource({endpoint: \"Security/Tenant\"});\r\n        var tenantGrid = new GridWidget(container, tenantData);\r\n        tenantGrid.groupable = false;\r\n        tenantGrid.filterable = true;\r\n        tenantGrid.editable = true;\r\n        tenantGrid.detailTemplate = $(\"[name=tenantDetails]\", container).first().html();\r\n        tenantGrid.columns = [\r\n            { field: \"Id\", title: \"[resource_shortdisplayname[Id]]\" },\r\n            { field: \"Name\", title: \"[resource_shortdisplayname[Name]]\" },\r\n            { field: \"Description\", title: \"[resource_shortdisplayname[Description]]\" },\r\n        ];\r\n        tenantGrid.commands.push({ name: \"save\", icon: \"k-i-save\", text: \"[resource_displayname[save]]\" });\r\n        tenantGrid.commands.push({ name: \"remove\", icon: \"k-i-trash\", text: \"[resource_displayname[remove]]\" });\r\n        tenantGrid.toolbar = `<button class=\"btn btn-sm btn-primary\" name='add'><span class='k-icon k-i-plus'></span>[resource_displayname[add]]</button>`;\r\n        tenantGrid.dataBound = function (e) {\r\n            $(\"[name=save]\", tenantGrid.gridElement).off(\"click\").on(\"click\", (e) => TenantManagement.save(e, tenantGrid));\r\n            $(\"[name=remove]\", tenantGrid.gridElement).off(\"click\").on(\"click\", (e) => TenantManagement.openRemoveDialog(container, e, tenantGrid));\r\n        };\r\n        tenantGrid.detailExpand = async (e) => {\r\n            if ($(\".k-tabstrip\", $(e.detailRow)).length > 0) {\r\n                return;\r\n            }\r\n\r\n            var tenantContainer = $(e.detailRow);\r\n            var tenant = tenantGrid.dataItem($(e.masterRow).closest(\"tr\"));\r\n            $(\"[name=tabs]\", $(e.detailRow)).kendoTabStrip({ animation: { open: { effects: \"fadeIn\" } } });\r\n\r\n            var apps = await loadComponent($(\".tab[name=apps]\", tenantContainer), \"TenantAppManagement\");\r\n            apps.init(app, $(\".component[name=TenantAppManagement]\", $(\".tab[name=apps]\", tenantContainer)), tenant);\r\n\r\n            var analytics = await loadComponent($(\"[name=analytics]\", tenantContainer), \"PlatformUsage\");\r\n            analytics.init({\r\n                Config: app.Config,\r\n                TenantId: tenant.Id\r\n            }, $(\".tab[name=analytics]\", tenantContainer));\r\n\r\n            var activity = await loadComponent($(\"[name=activity]\", tenantContainer), \"TenantActivity\");\r\n            activity.init(app, $(\"[name=activity]\", tenantContainer), tenant);\r\n        };\r\n\r\n        await tenantGrid.init();\r\n\r\n        $(\"[name=add]\", container).off(\"click\").on(\"click\", (e) => TenantManagement.newTenant(e, tenantGrid));\r\n    },\r\n\r\n    save: async function (e, grid) {\r\n        e.preventDefault();\r\n        var item = grid.dataItem($(e.currentTarget).closest(\"tr\"));\r\n        await api.update(\"Security/Tenant('\" + item.Id + \"')\").then(async () => {\r\n            notification.success(\"[resource_displayname[saved]]\");\r\n        }).catch((err) => error(err));\r\n    },\r\n\r\n    openRemoveDialog: async function(container, e, grid) {\r\n        var dialog = new Dialog({\r\n            width: 600,\r\n            height: 'auto',\r\n            title: '[resource_displayname[deletetenant]]?'\r\n        });\r\n        var tenant = grid.kendoObject.dataItem($(e.currentTarget).closest(\"tr\"));\r\n\r\n        dialog.template = $('[name=delete-tenant-template]', container).html();\r\n\r\n        \r\n        dialog.events.confirm = async () => {\r\n            var deleteRootBucket = $('[name=delete-root-bucket]', dialog.element).is(':checked');\r\n            var deleteClientCrmFolder = $('[name=delete-client-crm-folder]', dialog.element).is(':checked');\r\n\r\n            var apps = (await api.get(`ContentManagement/App?$filter=TenantId eq '${tenant.Id}'`)).value;\r\n\r\n            if(apps.length > 0) {\r\n                notification.error('[resource_displayname[tenantHasAppsCannotDelete]]');\r\n                return;\r\n            }\r\n\r\n            if(deleteRootBucket)\r\n                await TenantManagement.deleteTenantRootBucket(tenant);\r\n\r\n            if(deleteClientCrmFolder)\r\n                await TenantManagement.deleteClientCrmFolder(tenant);\r\n            \r\n            await TenantManagement.deleteTenantApps(tenant);\r\n            await TenantManagement.remove(e, grid);\r\n            \r\n            dialog.events.close();\r\n\r\n            grid.refresh();\r\n        };\r\n\r\n        dialog.init();\r\n    },\r\n\r\n    deleteClientCrmFolder: async function(tenant) {\r\n        var crmFolders = (await api.get(`DocumentManagement/Folder?$filter=AppId eq ${session.app.Id} and Path eq 'crm/${tenant.Id.toLowerCase()}'`)).value;\r\n        var clientFolders = (await api.get(`DocumentManagement/Folder?$filter=AppId eq ${session.app.Id} and Path eq 'clients/${tenant.Id.toLowerCase()}'`)).value;\r\n\r\n        if(crmFolders.length > 0)\r\n            for(var folder of crmFolders)\r\n                await api.file.destroy(folder.Path);\r\n                \r\n        if(clientFolders.length > 0)\r\n            for(var folder of clientFolders)\r\n                await api.file.destroy(folder.Path);\r\n    },\r\n\r\n    deleteTenantRootBucket: async function(tenant) {\r\n        // Transactions cleardown.\r\n        var tenantSystem = (await api.get(`B2B/System?$filter=Id eq '${tenant.Id}'`)).value;\r\n        if(tenantSystem.length == 0) {\r\n            notification.error(\"[resource_displayname[tenantSourceSystemNotFound]]\");\r\n            notification.info(\"[resource_description[tenantSourceSystemNotFound]]\");\r\n            return;\r\n        }\r\n\r\n        await api.destroy(`B2B/Transactions/ClearDown?sourceSystemId=${tenant.Id}`);\r\n\r\n        // Masterdata cleardown.\r\n        var buckets = (await api.get(`B2B/Bucket?$filter=Path eq '${tenant.Id}'`)).value;\r\n        if(buckets.length == 0) {\r\n            notification.info('[resource_displayname[rootBucketNotFound]]');\r\n            return;\r\n        }\r\n\r\n        var rootBucketId = buckets[0].Id;\r\n        notification.info('[resource_displayname[clearingDownMasterdata]]');\r\n        await api.post(`B2B/Bucket/ClearDown?rootBucketId=${rootBucketId}`);\r\n\r\n        // Delete root bucket.\r\n        await api.destroy(`B2B/Bucket(${rootBucketId})`);\r\n    },\r\n    \r\n    remove: async function (e, grid) {\r\n        e.preventDefault();\r\n        var item = grid.kendoObject.dataItem($(e.currentTarget).closest(\"tr\"));\r\n        await api.destroy(\"Security/Tenant('\" + item.Id + \"')\").then(async () => {\r\n            notification.success(\"[resource_displayname[tenantDeleted]]\");\r\n            grid.refresh();\r\n        }).catch((err) => error(err));\r\n    },\r\n\r\n    newTenant: async function (e, tenantGrid) {\r\n        e.preventDefault();\r\n        var validator = null;\r\n        var newTenantDialog = new Dialog({\r\n            width: 600,\r\n            height: \"auto\",\r\n            title: \"[resource_displayname[newtenant]]\"\r\n        });\r\n        newTenantDialog.template = $(\"[name=newTenantDialog]\").html();\r\n        newTenantDialog.events.create = async function (e) {\r\n            if (!validator.validate()) {\r\n                return;\r\n            }\r\n\r\n            var tenant = {\r\n                Id: $(\"[name=name]\", newTenantDialog.element).val(),\r\n                Name: $(\"[name=name]\", newTenantDialog.element).val(),\r\n                Description: $(\"[name=description]\", newTenantDialog.element).val(),\r\n                CreatedOn: (new Date()).toISOString(),\r\n                LastUpdated: (new Date()).toISOString(),\r\n                CreatedBy: session.user,\r\n                LastUpdatedBy: session.user,\r\n            };\r\n\r\n            await api.add(\"Security/Tenant\", tenant).then(async () => {\r\n                notification.success(\"[resource_displayname[added]]\");\r\n                tenantGrid.refresh();\r\n            }).catch((err) => error(err));\r\n            \r\n            newTenantDialog.events.close();\r\n        };\r\n        newTenantDialog.init();\r\n       \r\n        validator = newTenantDialog.element.kendoValidator().data(\"kendoValidator\");\r\n    },\r\n\r\n    deleteTenantApps: async function(tenant) {\r\n        var apps = (await api.get(`ContentManagement/App?$filter=TenantId eq '${tenant.Id}'`)).value;\r\n\r\n        for(var app of apps)\r\n            await api.destroy(`ContentManagement/App(${app.Id})`);\r\n    }\r\n}",
  "Content": "<script type=\"text/template\" name=\"tenantDetails\">\r\n\t<div name=\"tabs\">\r\n\t\t<ul>\r\n\t\t\t<li class=\"k-active\">[resource_displayname[apps]]</li>\r\n\t\t\t<li>[resource_displayname[analytics]]</li>\r\n\t\t\t<li>[resource_displayname[activity]]</li>\r\n\t\t</ul>\r\n\r\n\t\t<div class=\"tab\" name=\"apps\"></div>\r\n\t\t<div class=\"tab\" name=\"analytics\"></div>\r\n\t\t<div class=\"tab\" name=\"activity\"></div>\r\n\t</div>\r\n</script>\r\n\r\n<script type=\"text/template\" name=\"newTenantDialog\">\r\n\t<div class=\"input-group input-group-sm mb-3\">\r\n\t\t<input type=\"text\" name=\"name\" class=\"form-control\" aria-label=\"[resource_displayname[name]]\" placeholder=\"[resource_displayname[name]]\" required />\r\n\t</div>\r\n\t<div class=\"input-group input-group-sm mb-3\">\r\n\t\t<input type=\"text\" name=\"description\" class=\"form-control\" aria-label=\"[resource_displayname[description]]\" placeholder=\"[resource_displayname[description]]\" required />\r\n\t</div>\r\n\t<hr />\r\n\t<div class=\"input-group input-group-sm mb-3 justify-content-end\">\r\n\t\t<button type=\"button\" class=\"btn btn-sm btn-primary\" name=\"create\">\r\n\t\t\t<span class=\"k-icon k-i-plus\"></span>[resource_displayname[add]]\r\n\t\t</button>\r\n\t</div>\r\n</script>\r\n\r\n<script type=\"text/template\" name=\"delete-tenant-template\">\r\n\t<h3 class=\"red\">\r\n\t\t[resource_displayname[deletingTenantWillDeleteApps]]\r\n\t</h3>\r\n\r\n\t<div class=\"input-group input-group-sm mb-3\">\r\n\t\t<div class=\"input-group-text\">\r\n\t\t\t<input class=\"form-check-input mt-0\" type=\"checkbox\" name=\"delete-root-bucket\" aria-label=\"[resource_displayname[deleteRootBucket]]?\">\r\n\t\t</div>\r\n\t\t<input type=\"text\" class=\"form-control\" disabled placeholder=\"[resource_displayname[deleteRootBucket]]?\">\r\n\t</div>\r\n\r\n\t<div class=\"input-group input-group-sm mb-3\">\r\n\t\t<div class=\"input-group-text\">\r\n\t\t\t<input class=\"form-check-input mt-0\" type=\"checkbox\" name=\"delete-client-crm-folder\" aria-label=\"[resource_displayname[deleteClientCrmFolder]]?\">\r\n\t\t</div>\r\n\t\t<input type=\"text\" class=\"form-control\" disabled placeholder=\"[resource_displayname[deleteClientCrmFolder]]?\">\r\n\t</div>\r\n\r\n\t<hr />\r\n\r\n\t<div class=\"btn-group btn-group-sm float-end\">\r\n\t\t<button class=\"btn btn-primary\" name=\"confirm\">\r\n\t\t\t<span class=\"k-icon k-i-trash\"></span> [resource_displayname[deletetenant]]\r\n\t\t</button>\r\n\t</div>\r\n</script>",
  "LastUpdated": "2026-03-02T10:19:34.614782+00:00"
}
