{
  "Name": "TenantThemeManagement",
  "Key": "CRM",
  "ResourceKey": "CRM",
  "Script": "TenantThemeManagement = {\r\n    init: async function (app, container, tenant) {\r\n        app = app || session.app;\r\n        container = container || $(\".component[name=TenantThemeManagement]\");\r\n        TenantThemeManagement.initBrandLogoFileUpload(container, tenant);\r\n        TenantThemeManagement.initProjectLogoFileUpload(container, tenant);\r\n        TenantThemeManagement.initBackgroundFileUpload(container, tenant);\r\n        var defaultTheme =\r\n        {\r\n            \"margins\": \"4px\",\r\n            \"paintLoginMid\": false,\r\n            \"paintLoginBottom\": false,\r\n            \"colours\": {\r\n                \"primary\": \"#2e4b75\",\r\n                \"secondary\": \"#EE8A00\",\r\n                \"background\": \"white\",\r\n                \"text\": \"#222\",\r\n                \"text2\": \"#FFFFFF\",\r\n                \"links\": \"#214A71\",\r\n                \"error\": \"red\",\r\n                \"charts\": [\r\n                    \"#FF1A0C\",\r\n                    \"#484848\",\r\n                    \"#484848\",\r\n                    \"#FF1A0C\",\r\n                    \"#484848\",\r\n                    \"#FF1A0C\"\r\n                ],\r\n                \"margins\": \"8px\"\r\n            },\r\n            \"font\": {\r\n                \"size\": \"11px\",\r\n                \"family\": \"Quicksand, sans-serif\"\r\n            },\r\n            \"border\": {\r\n                \"style\": \"solid 1px #ccc\",\r\n                \"width\": \"1px\",\r\n                \"radius\": 0\r\n            },\r\n            \"notifications\": {\r\n                \"error\": {\r\n                    \"text\": \"#222\",\r\n                    \"background\": \"#FFECEC\"\r\n                },\r\n                \"warning\": {\r\n                    \"text\": \"#222\",\r\n                    \"background\": \"#FFF4D9\"\r\n                },\r\n                \"info\": {\r\n                    \"text\": \"#222\",\r\n                    \"background\": \"#E5F5FA\"\r\n                },\r\n                \"success\": {\r\n                    \"text\": \"#222\",\r\n                    \"background\": \"#EAF7EC\"\r\n                }\r\n            },\r\n            \"shadows\": \"2px 2px 5px #333\"\r\n        }\r\n        var theme = await api.get(\"DMS/CRM/\" + tenant.Id + \"/Theme/Colours/colours.json\").catch(async () => {\r\n            await api.post(\"DMS/CRM/\" + tenant.Id + \"/Theme/Colours/colours.json\", {\r\n                \"Default\": defaultTheme\r\n            });\r\n        })\r\n\r\n        var theme = (await api.get(\"DMS/CRM/\" + tenant.Id + \"/Theme/Colours/colours.json\"));\r\n        $(\"[name=primaryPicker]\", container).kendoColorPicker({ \r\n            value: theme.colours.primary, \r\n            buttons: false, \r\n            views: [\"gradient\"],\r\n            change: (e) => e.preventDefault() \r\n            });\r\n        $(\"[name=secondaryPicker]\", container).kendoColorPicker({ \r\n            value: theme.colours.secondary, \r\n            buttons: false, \r\n            views: [\"gradient\"],\r\n            change: (e) => e.preventDefault() \r\n            });\r\n        $(\"[name=chartColour1]\", container).kendoColorPicker({ \r\n            value: theme.colours.charts[2], \r\n            buttons: false, \r\n            views: [\"gradient\"],\r\n            change: (e) => e.preventDefault() \r\n            });\r\n        $(\"[name=chartColour2]\", container).kendoColorPicker({ \r\n            value: theme.colours.charts[3], \r\n            buttons: false, \r\n            views: [\"gradient\"],\r\n            change: (e) => e.preventDefault() \r\n            });\r\n        $(\"[name=chartColour3]\", container).kendoColorPicker({ \r\n            value: theme.colours.charts[4], \r\n            buttons: false, \r\n            views: [\"gradient\"],\r\n            change: (e) => e.preventDefault() \r\n            });\r\n        $(\"[name=chartColour4]\", container).kendoColorPicker({ \r\n            value: theme.colours.charts[5], \r\n            buttons: false, \r\n            views: [\"gradient\"],\r\n            change: (e) => e.preventDefault() \r\n            });\r\n        if (!tenant) {\r\n            return;\r\n        }\r\n        await api.post(\"DMS/CRM/\" + tenant.Id + \"/Theme/Content\");\r\n        await api.post(\"DMS/CRM/\" + tenant.Id + \"/Theme/Content/Slideshow\");\r\n        await api.post(\"DMS/CRM/\" + tenant.Id + \"/Theme/Colours\");\r\n         var slideshow = (await api.get(\"DocumentManagement/Folder?$filter=AppId eq \" + app.Id + \" and Path eq 'CRM/\"+ tenant.Id + \"/Theme/Content/Slideshow'&$expand=Files\")).value[0];\r\n        FolderManagement.init(app, $(\".component[name=FolderManagement]\", $(\"[name=uploadSlideshowImages]\", container)), slideshow, true, true);\r\n        $(\"[name=save]\", container).off(\"click\").on(\"click\", async (e) => await TenantThemeManagement.saveTheme(e, container, theme, tenant));\r\n   },\r\n\r\n    saveTheme: async function (e, container, theme, tenant) {\r\n        e.preventDefault();\r\n        theme.colours.primary = $(\"[name=primaryPicker]\", container).val();\r\n        theme.colours.secondary = $(\"[name=secondaryPicker]\", container).val();\r\n\r\n        theme.colours.charts[0] = $(\"[name=primaryPicker]\", container).val();\r\n        theme.colours.charts[1] = $(\"[name=secondaryPicker]\", container).val();\r\n        theme.colours.charts[2] = $(\"[name=chartColour1]\", container).val();\r\n        theme.colours.charts[3] = $(\"[name=chartColour2]\", container).val();\r\n        theme.colours.charts[4] = $(\"[name=chartColour3]\", container).val();\r\n        theme.colours.charts[5] = $(\"[name=chartColour4]\", container).val();\r\n        \r\n        await api.post(\"DMS/CRM/\" + tenant.Id + \"/Theme/Colours/colours.json\", theme).then(() => {\r\n            notification.success(\"Saved\");\r\n        }).catch((err) => error(err));\r\n    },\r\n\r\n        initProjectLogoFileUpload: function (container, tenant) {\r\n        var projectLogoInput = $(\"[name=projectLogoInput]\", container);\r\n        var projectLogoButton = $(\"[name=projectLogoButton]\", container); \r\n\r\n        projectLogoButton.on(\"click\", async function () {\r\n            projectLogoInput.trigger(\"click\");\r\n        });\r\n\r\n        projectLogoInput.on(\"change\", async function (e) {\r\n            var file = e.target.files[0];\r\n            await api.file.upload(\"CRM/\" + tenant.Id + \"/Theme/Content/CompanyLogo2.png\", file);\r\n            $(\"[name=projectLogo]\", container).attr(\"src\", \"[api[root]]/DMS/CRM/\" + tenant.Id + \"/Theme/Content/CompanyLogo2.png?time=\" + (new Date()).toISOString());\r\n        });\r\n    },\r\n\r\n    initBrandLogoFileUpload: function (container, tenant) {\r\n        var brandLogoInput = $(\"[name=brandLogoInput]\", container);\r\n        var brandLogoButton = $(\"[name=brandLogoButton]\", container); \r\n\r\n        brandLogoButton.on(\"click\", async function () {\r\n            brandLogoInput.trigger(\"click\");\r\n        });\r\n\r\n        brandLogoInput.on(\"change\", async function (e) {\r\n            var file = e.target.files[0];\r\n            await api.file.upload(\"CRM/\" + tenant.Id + \"/Theme/Content/CompanyLogo.png\", file);\r\n            $(\"[name=brandLogo]\", container).attr(\"src\", \"[api[root]]/DMS/CRM/\" + tenant.Id + \"/Theme/Content/CompanyLogo.png?time=\" + (new Date()).toISOString());\r\n        });\r\n    },\r\n\r\n    initBackgroundFileUpload: function (container, tenant) {\r\n        var backgroundAnimationInput = $(\"[name=backgroundAnimationInput]\", container);\r\n        var backgroundAnimationButton = $(\"[name=backgroundAnimationButton]\", container);\r\n\r\n        backgroundAnimationButton.on(\"click\", async function () {\r\n            backgroundAnimationInput.trigger(\"click\");\r\n        });\r\n\r\n        backgroundAnimationInput.on(\"change\", async function (e) {\r\n            var file = e.target.files[0];\r\n            await api.file.upload(\"CRM/\" + tenant.Id + \"/Theme/Content/background.png\", file);\r\n            $(\"[name=backgroundAnimation]\", container).attr(\"src\", \"[api[root]]/DMS/CRM/\" + tenant.Id + \"/Theme/Content/background.png?time=\" + (new Date()).toISOString());\r\n        });\r\n    }\r\n}",
  "Content": "<div class=\"appTheme\">\r\n<ul class=\"fieldList theming\">\r\n\t<li>\r\n\t\t<label>[resource_displayname[primary]]</label>\r\n\t\t<div class=\"value\">\r\n\t\t\t<input  name=\"primaryPicker\" />\r\n\t\t\t</div>\r\n\t</li>\r\n\t<li>\r\n\t\t<label>[resource_displayname[secondary]]</label>\r\n\t\t<div class=\"value\">\r\n\t\t\t<input name=\"secondaryPicker\" />\r\n\t\t\t</div>\r\n\t</li>\r\n\t<li>\r\n\t\t<label>[resource_displayname[chartcolour1]]</label>\r\n\t\t<div class=\"value\">\r\n\t\t\t<input name=\"chartColour1\" />\r\n\t\t</div>\r\n\t</li>\r\n\t<li>\r\n\t\t<label>[resource_displayname[chartcolour2]]</label>\r\n\t\t<div class=\"value\">\r\n\t\t\t<input name=\"chartColour2\" />\r\n\t\t</div>\r\n\t</li>\r\n\t<li>\r\n\t\t<label>[resource_displayname[chartcolour3]]</label>\r\n\t\t<div class=\"value\">\r\n\t\t\t<input name=\"chartColour3\" />\r\n\t\t</div>\r\n\t</li>\r\n\t<li>\r\n\t\t<label>[resource_displayname[chartcolour4]]</label>\r\n\t\t<div class=\"value\">\r\n\t\t\t<input name=\"chartColour4\" />\r\n\t\t</div>\r\n\t</li>\r\n\t<li>\r\n\t\t<label>[resource_displayname[brandlogo]]</label>\r\n\t\t<div class=\"value\">\r\n\t\t\t<input type=\"file\" name=\"brandLogoInput\" style=\"display: none;\" />\r\n\t\t\t<button name=\"brandLogoButton\"> <span class=\"k-icon k-i-upload\"></span>[resource_displayname[uploadbrandlogo]]</button>\r\n\t\t</div>\r\n\t</li>\r\n\t\t<li>\r\n\t\t<label>[resource_displayname[projectLogo]]</label>\r\n\t\t<div class=\"value\">\r\n\t\t\t<input type=\"file\" name=\"projectLogoInput\" style=\"display: none;\" />\r\n\t\t\t<button name=\"projectLogoButton\"><span class=\"k-icon k-i-upload\"></span>[resource_displayname[uploadprojectlogo]]</button>\r\n\t\t</div>\r\n\t</li>\r\n\t<li>\r\n\t\t<label>[resource_displayname[animation]]</label>\r\n\t\t<div class=\"value\">\r\n\t\t\t<input type=\"file\" name=\"backgroundAnimationnput\" style=\"display: none;\" />\r\n\t\t\t<button name=\"backgroundAnimationButton\"><span class=\"k-icon k-i-upload\"></span>[resource_displayname[uploadbackgroundanimation]]</button>\r\n\t\t</div>\r\n\t</li>\r\n</ul>\r\n<ul class=\"fieldList theming\">\r\n\t<li>\r\n\t\t<label>[resource_displayname[uploadslideshowimages]]</label>\r\n\t\t<div class=\"value\" name=\"uploadSlideshowImages\" >\r\n\t\t\t[component[FolderManagement]]\r\n\t\t</div>\r\n\t</li>\r\n</ul>\r\n</div>\r\n<hr>\r\n<div class=\"value\">\r\n\t<button name=\"save\"><span class='k-icon k-i-save'></span>[resource_shortdisplayname[save]]</button>\r\n</div>\r\n\r\n\r\n<style scoped>\r\n\tdiv[name=appThemeList]  {width: 400px; height: 400px; }\r\n\timg[name=projectLogo] { width: 200px;height: 100px;}\r\n\timg[name=brandLogo] { width: 200px;height: 100px; }\r\n\timg[name=backgroundAnimation] {width: 200px;height: 100px;}\r\n\t.fileUploaderTag {top: 0px;left: 0px;width: 100%;height: 100%;opacity: 0;position: absolute;z-index: 999;}\r\n\t.k-color-preview-mask {z-index: unset !important; }\r\n\t.theming { max-width: 49vw; } \r\n    .appTheme{ flex-direction: row; display: flex; flex:1; }\r\n\t.component[name=FolderManagement] { max-width: 700px; max-height: 300px;}\r\n\t.component[name=TenantThemeManagement] { width:calc(100% - ((1px + 4px) * 2)) !important; }\r\n</style>",
